    qs.append("cmd", "bash");
    qs.append("cmd", "-lc");
    qs.append("cmd", data.script);

    const res = await fetch(`${API}/sprites/${name}/exec?${qs}`, {
      method: "POST",
      headers: auth(),
    });
    if (!res.ok) throw new Error(`Sprite exec failed: ${res.status}`);

